{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Membership Options — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfdfc;--panel:#ffffff;--muted:#6b6f74;--accent:#00695c;--accent-2:#00a896;--glass:rgba(0,0,0,0.04);font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#f2fbfa)}
    .wrap{max-width:980px;margin:32px auto;padding:28px}
    header{display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:48px;height:48px;background:var(--accent);border-radius:10px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none}
    .hero{background:var(--panel);border-radius:12px;padding:22px;margin-top:18px;box-shadow:0 6px 20px var(--glass)}
    .hero h1{margin:0;font-size:20px;color:#073b39}
    .hero p{color:var(--muted);margin:8px 0 0}
    .layout{display:grid;grid-template-columns:1fr 340px;gap:18px;margin-top:18px}
    .cards{display:flex;gap:12px;flex-direction:column}
    .card{background:linear-gradient(180deg,#fff,#fbfffe);padding:16px;border-radius:10px;border:1px solid rgba(3,40,38,0.04)}
    .card h3{margin:0 0 6px;color:#034040}
    .price{font-size:22px;color:var(--accent)}
    .muted{color:var(--muted);font-size:13px}
    .selector{margin-top:12px;padding:12px;background:#f8fffe;border-radius:10px}
    .moods{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
    .mood{padding:8px 10px;border-radius:8px;background:#fff;border:1px solid rgba(3,40,38,0.06);cursor:pointer}
    .mood.active{background:var(--accent);color:#fff;border-color:rgba(0,0,0,0.06)}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none}
    .side{position:relative}
    .pattern{position:absolute;inset:0;opacity:0.06;pointer-events:none}
    .toggle{display:flex;gap:8px;align-items:center;margin-top:10px}
    .pill{background:#eef7f6;padding:6px 10px;border-radius:999px;font-size:13px;color:#035451}
    footer{margin-top:28px;color:var(--muted);font-size:13px}
    /* simple responsive */
    @media(max-width:880px){.layout{grid-template-columns:1fr}.side{order:2}.cards{order:1}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">
        <div class="logo">W</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">Philosophy</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Membership</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html">Schedule</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <section class="hero">
      <h1>Membership plans built around steady progress</h1>
      <p>Focused practices, measurable habits, and a coach-guided rhythm designed for sustainable results. Pick a level that fits the cadence you want.</p>
    </section>

    <div class="layout">
      <div>
        <div class="cards">
          <div class="card">
            <h3>Compass Membership</h3>
            <div class="price" id="price-one">$79 / month</div>
            <div class="muted">Weekly check-ins, habit tracking, resource library</div>
            <ul style="margin:12px 0 0;color:var(--muted)">
              <li>Structured habit plan (30-day focus)</li>
              <li>Monthly tune-up session</li>
              <li>Access to group workshops</li>
            </ul>
            <a id="cta-one" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div class="card">
            <h3>Steady Habits Plan</h3>
            <div class="price" id="price-two">$149 / month</div>
            <div class="muted">Personalized framework, twice-monthly coaching, priority booking</div>
            <ul style="margin:12px 0 0;color:var(--muted)">
              <li>Custom 30-day roadmap</li>
              <li>Weekly touchpoints via message</li>
              <li>Tools for building repeatable routines</li>
            </ul>
            <a id="cta-two" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div class="card">
            <h3>Pulse Reset — Short Course</h3>
            <div class="price" id="price-three">$295</div>
            <div class="muted">A concise reset plan (four sessions) to relocate energy and test routines</div>
            <a id="cta-three" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
      </div>

      <aside class="side">
        <svg class="pattern" width="100%" height="220" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 220" preserveAspectRatio="none">
          <defs>
            <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#e8fffb"/><stop offset="1" stop-color="#f6fffef"/></linearGradient>
          </defs>
          <rect width="600" height="220" fill="url(#g1)"/>
          <g fill="none" stroke="#bdeee6" stroke-opacity="0.6" stroke-width="1">
            <path d="M0 40c80 10 120 0 220 20s150 10 220 0 160-40 240-20"/>
            <path d="M0 120c70-20 130-10 200-10s120 30 200 10 140-30 200 0"/>
          </g>
        </svg>
        <div class="selector card">
          <strong>How are you feeling right now?</strong>
          <div class="moods" role="list" id="moodList">
            <button class="mood" data-mode="calm">Balanced</button>
            <button class="mood" data-mode="stretched">Stretched</button>
            <button class="mood" data-mode="flat">Low energy</button>
            <button class="mood" data-mode="wired">Overstimulated</button>
          </div>

          <div id="moodRec" style="margin-top:14px;color:var(--muted)">Choose a current state to see an approach tailored to today.</div>
          <div style="margin-top:12px">
            <span class="pill" id="moodPill">Recommendation</span>
            <a id="moodCta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div style="font-size:12px;color:var(--muted);margin-top:10px">Toggle billing</div>
          <div class="toggle">
            <button id="monthlyBtn" class="pill">Monthly</button>
            <button id="annualBtn" class="pill" style="opacity:0.6">Annual</button>
          </div>
        </div>
      </aside>
    </div>

    <footer>
      <div>Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    (function(){
      const moods = document.querySelectorAll('.mood');
      const moodRec = document.getElementById('moodRec');
      const moodPill = document.getElementById('moodPill');
      const moodCta = document.getElementById('moodCta');

      const recommendations = {
        calm: {label:'Refine routine',desc:'Light tuning: maintain what works and add one tiny habit to amplify stability.',cta:'Start a steady check-in'},
        stretched: {label:'Structure first',desc:'Short, focused actions to reduce load and create breathable moments in each day.',cta:'Begin with a short reset'},
        flat: {label:'Lift small wins',desc:'Micro-habits to lift momentum — short wins stacked across the week.',cta:'Try a momentum plan'},
        wired: {label:'Anchor & downshift',desc:'Rhythms that help reduce reactivity and mark predictable rest windows.',cta:'Book an anchor session'}
      };

      moods.forEach(btn=>btn.addEventListener('click',()=>{
        moods.forEach(b=>b.classList.remove('active'));
        btn.classList.add('active');
        const mode = btn.getAttribute('data-mode');
        const rec = recommendations[mode] || recommendations.calm;
        moodRec.textContent = rec.desc;
        moodPill.textContent = rec.label;
        moodCta.textContent = rec.cta + ' — ' + window.location.hostname;
        // update all CTAs across the page for demonstration
        document.querySelectorAll('.cta').forEach(a=>{
          a.setAttribute('data-origin-label',a.textContent);
          a.textContent = rec.cta;
        });
      }));

      // billing toggle
      let annual = false;
      const monthlyBtn = document.getElementById('monthlyBtn');
      const annualBtn = document.getElementById('annualBtn');
      monthlyBtn.addEventListener('click',()=>setBilling(false));
      annualBtn.addEventListener('click',()=>setBilling(true));
      function setBilling(isAnnual){
        annual = isAnnual;
        monthlyBtn.style.opacity = isAnnual?0.6:1;
        annualBtn.style.opacity = isAnnual?1:0.6;
        if(isAnnual){
          document.getElementById('price-one').textContent = '$790 / year';
          document.getElementById('price-two').textContent = '$1490 / year';
          document.getElementById('price-three').textContent = '$995 / year';
        } else {
          document.getElementById('price-one').textContent = '$79 / month';
          document.getElementById('price-two').textContent = '$149 / month';
          document.getElementById('price-three').textContent = '$295';
        }
      }

      // initialize
      setBilling(false);
    })();
  </script>
</body>
</html>"} 
