<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Stories — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--panel:#fbfffe;--muted:#55606a;--accent:#007a72;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial}
    body{margin:0;background:linear-gradient(180deg,#fbfffe,#f6fbfb);color:#042a29}
    .container{max-width:980px;margin:28px auto;padding:26px}
