    .quote{font-style:italic;color:#053737}
    .meta{font-size:13px;color:var(--muted);margin-top:8px}
    .control{background:#f0fffd;padding:10px;border-radius:10px}
    .thumbs{display:flex;gap:8px;margin-top:8px}
    .thumb{width:48px;height:48px;border-radius:8px;background:#e6fff9;display:flex;align-items:center;justify-content:center;color:#06504b;cursor:pointer}
    .selected{outline:3px solid rgba(0,122,114,0.12)}
